//! kvhttp: an in-memory HTTP/1.1 key-value server.
//!
//! Usage: `app <port>` — listens on `127.0.0.1:<port>` until killed.

mod routes;
mod server;
mod store;

use std::process::ExitCode;

fn parse_port(arg: &str) -> Option<u16> {
    arg.parse().ok().filter(|&port| port != 0)
}

#[tokio::main]
async fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    let port = match args.as_slice() {
        [_, port] => parse_port(port),
        _ => None,
    };
    let Some(port) = port else {
        let program = args.first().map_or("app", String::as_str);
        eprintln!("usage: {program} <port>");
        return ExitCode::from(2);
    };

    match server::run(port).await {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("error: {err}");
            ExitCode::FAILURE
        }
    }
}

//! Maps HTTP requests onto key-value store operations.

use bytes::Bytes;
use http_body_util::Full;
use hyper::header::{CONTENT_TYPE, HeaderValue};
use hyper::{Method, Response, StatusCode};

use crate::store::Store;

/// Longest accepted key, in bytes.
pub const MAX_KEY_LEN: usize = 64;
/// Largest accepted value (and request body), in bytes.
pub const MAX_VALUE_LEN: usize = 1024 * 1024;

const KV_PREFIX: &str = "/kv/";

/// The resource a request path refers to.
#[derive(Debug, PartialEq, Eq)]
enum Resource<'a> {
    Health,
    Keys,
    Item(&'a str),
    InvalidKey,
    Unknown,
}

impl<'a> Resource<'a> {
    fn from_path(path: &'a str) -> Self {
        match path {
            "/health" => Self::Health,
            "/kv" => Self::Keys,
            _ => match path.strip_prefix(KV_PREFIX) {
                Some(key) if is_valid_key(key) => Self::Item(key),
                Some(_) => Self::InvalidKey,
                None => Self::Unknown,
            },
        }
    }
}

/// A key matches `[A-Za-z0-9_-]{1,64}`.
pub fn is_valid_key(key: &str) -> bool {
    (1..=MAX_KEY_LEN).contains(&key.len())
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

/// Handles one fully received request.
pub fn handle(store: &Store, method: &Method, path: &str, body: Bytes) -> Response<Full<Bytes>> {
    match Resource::from_path(path) {
        Resource::Health if method == Method::GET => respond(
            StatusCode::OK,
            Some("text/plain"),
            Bytes::from_static(b"ok"),
        ),
        Resource::Keys if method == Method::GET => list_keys(store),
        Resource::Item(key) => handle_item(store, method, key, body),
        Resource::Health | Resource::Keys => status(StatusCode::METHOD_NOT_ALLOWED),
        Resource::InvalidKey => status(StatusCode::BAD_REQUEST),
        Resource::Unknown => status(StatusCode::NOT_FOUND),
    }
}

fn handle_item(store: &Store, method: &Method, key: &str, body: Bytes) -> Response<Full<Bytes>> {
    match *method {
        Method::GET => match store.get(key) {
            Some(value) => respond(StatusCode::OK, Some("application/octet-stream"), value),
            None => status(StatusCode::NOT_FOUND),
        },
        Method::PUT => {
            if store.put(key, body) {
                status(StatusCode::CREATED)
            } else {
                status(StatusCode::OK)
            }
        }
        Method::DELETE => {
            if store.delete(key) {
                status(StatusCode::NO_CONTENT)
            } else {
                status(StatusCode::NOT_FOUND)
            }
        }
        _ => status(StatusCode::METHOD_NOT_ALLOWED),
    }
}

/// Serializes all keys as a sorted JSON array. Valid keys never need escaping.
fn list_keys(store: &Store) -> Response<Full<Bytes>> {
    let keys = store.keys();
    let mut json = String::with_capacity(2 + keys.iter().map(|k| k.len() + 3).sum::<usize>());
    json.push('[');
    for (i, key) in keys.iter().enumerate() {
        if i > 0 {
            json.push(',');
        }
        json.push('"');
        json.push_str(key);
        json.push('"');
    }
    json.push(']');
    respond(StatusCode::OK, Some("application/json"), Bytes::from(json))
}

/// A response with an empty body.
pub fn status(code: StatusCode) -> Response<Full<Bytes>> {
    respond(code, None, Bytes::new())
}

fn respond(
    code: StatusCode,
    content_type: Option<&'static str>,
    body: Bytes,
) -> Response<Full<Bytes>> {
    let mut response = Response::new(Full::new(body));
    *response.status_mut() = code;
    if let Some(content_type) = content_type {
        response
            .headers_mut()
            .insert(CONTENT_TYPE, HeaderValue::from_static(content_type));
    }
    response
}

#[cfg(test)]
mod tests {
    use super::*;
    use http_body_util::BodyExt;

    fn call(store: &Store, method: Method, path: &str, body: &'static [u8]) -> (StatusCode, Bytes) {
        let response = handle(store, &method, path, Bytes::from_static(body));
        let code = response.status();
        let body = collect_body(response.into_body());
        (code, body)
    }

    fn collect_body(body: Full<Bytes>) -> Bytes {
        let rt = tokio::runtime::Builder::new_current_thread()
            .build()
            .unwrap();
        rt.block_on(body.collect()).unwrap().to_bytes()
    }

    #[test]
    fn key_validation() {
        assert!(is_valid_key("a"));
        assert!(is_valid_key("A-z_09"));
        assert!(is_valid_key(&"k".repeat(MAX_KEY_LEN)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key(&"k".repeat(MAX_KEY_LEN + 1)));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("a.b"));
        assert!(!is_valid_key("a%20"));
        assert!(!is_valid_key("é"));
    }

    #[test]
    fn routing() {
        assert_eq!(Resource::from_path("/health"), Resource::Health);
        assert_eq!(Resource::from_path("/kv"), Resource::Keys);
        assert_eq!(Resource::from_path("/kv/x"), Resource::Item("x"));
        assert_eq!(Resource::from_path("/kv/"), Resource::InvalidKey);
        assert_eq!(Resource::from_path("/kv/a/b"), Resource::InvalidKey);
        assert_eq!(Resource::from_path("/kvx"), Resource::Unknown);
        assert_eq!(Resource::from_path("/health/"), Resource::Unknown);
        assert_eq!(Resource::from_path("/"), Resource::Unknown);
    }

    #[test]
    fn crud_and_errors() {
        let store = Store::new();
        assert_eq!(call(&store, Method::GET, "/health", b"").1, "ok");
        assert_eq!(
            call(&store, Method::POST, "/health", b"").0,
            StatusCode::METHOD_NOT_ALLOWED
        );
        assert_eq!(
            call(&store, Method::PUT, "/kv/b", b"2").0,
            StatusCode::CREATED
        );
        assert_eq!(
            call(&store, Method::PUT, "/kv/a", b"1").0,
            StatusCode::CREATED
        );
        assert_eq!(call(&store, Method::PUT, "/kv/a", b"one").0, StatusCode::OK);
        assert_eq!(
            call(&store, Method::GET, "/kv/a", b""),
            (StatusCode::OK, Bytes::from_static(b"one"))
        );
        assert_eq!(call(&store, Method::GET, "/kv", b"").1, r#"["a","b"]"#);
        assert_eq!(
            call(&store, Method::DELETE, "/kv/a", b"").0,
            StatusCode::NO_CONTENT
        );
        assert_eq!(
            call(&store, Method::DELETE, "/kv/a", b"").0,
            StatusCode::NOT_FOUND
        );
        assert_eq!(
            call(&store, Method::GET, "/kv/a", b"").0,
            StatusCode::NOT_FOUND
        );
        assert_eq!(
            call(&store, Method::PATCH, "/kv/a", b"").0,
            StatusCode::METHOD_NOT_ALLOWED
        );
        assert_eq!(
            call(&store, Method::PUT, "/kv", b"").0,
            StatusCode::METHOD_NOT_ALLOWED
        );
        assert_eq!(
            call(&store, Method::PATCH, "/kv/a.b", b"").0,
            StatusCode::BAD_REQUEST
        );
        assert_eq!(
            call(&store, Method::GET, "/nope", b"").0,
            StatusCode::NOT_FOUND
        );
    }
}

//! Accept loop and per-connection HTTP/1.1 handling.

use std::io;
use std::net::{Ipv4Addr, SocketAddr};
use std::sync::Arc;
use std::time::Duration;

use bytes::{Bytes, BytesMut};
use http_body_util::{BodyExt, Full};
use hyper::body::Incoming;
use hyper::server::conn::http1;
use hyper::service::service_fn;
use hyper::{Request, Response, StatusCode};
use hyper_util::rt::{TokioIo, TokioTimer};
use tokio::net::{TcpListener, TcpStream};

use crate::routes::{self, MAX_VALUE_LEN};
use crate::store::Store;

/// Overall budget for one connection (receiving the request and sending the reply).
const CONNECTION_TIMEOUT: Duration = Duration::from_secs(30);
/// How long a client may take to send the request head.
const HEADER_READ_TIMEOUT: Duration = Duration::from_secs(10);
/// Oversized bodies are read and discarded up to this many bytes before the
/// 413 is sent, so that closing the socket does not reset the connection and
/// destroy the response before the client reads it.
const MAX_DRAIN_LEN: usize = 16 * MAX_VALUE_LEN;
/// Pause after a failed `accept` (e.g. out of file descriptors) to avoid spinning.
const ACCEPT_BACKOFF: Duration = Duration::from_millis(50);

/// Binds `127.0.0.1:port` and serves until the process is killed.
pub async fn run(port: u16) -> io::Result<()> {
    let listener = TcpListener::bind(SocketAddr::from((Ipv4Addr::LOCALHOST, port))).await?;
    let store = Arc::new(Store::new());

    loop {
        match listener.accept().await {
            Ok((stream, _)) => {
                tokio::spawn(serve(stream, Arc::clone(&store)));
            }
            Err(err) => {
                eprintln!("accept: {err}");
                tokio::time::sleep(ACCEPT_BACKOFF).await;
            }
        }
    }
}

async fn serve(stream: TcpStream, store: Arc<Store>) {
    // Best effort: a failure only affects latency.
    let _ = stream.set_nodelay(true);

    let service = service_fn(move |request| handle(Arc::clone(&store), request));
    let connection = http1::Builder::new()
        .timer(TokioTimer::new())
        .header_read_timeout(HEADER_READ_TIMEOUT)
        .serve_connection(TokioIo::new(stream), service);

    // Errors here are per-connection (client went away, malformed request,
    // timeout) and need no action beyond dropping the connection.
    let _ = tokio::time::timeout(CONNECTION_TIMEOUT, connection).await;
}

async fn handle(
    store: Arc<Store>,
    request: Request<Incoming>,
) -> Result<Response<Full<Bytes>>, hyper::Error> {
    let (parts, body) = request.into_parts();
    let response = match read_body(body).await? {
        Some(body) => routes::handle(&store, &parts.method, parts.uri.path(), body),
        None => routes::status(StatusCode::PAYLOAD_TOO_LARGE),
    };
    Ok(response)
}

/// Collects the request body, or returns `None` if it exceeds `MAX_VALUE_LEN`.
async fn read_body(mut body: Incoming) -> Result<Option<Bytes>, hyper::Error> {
    let mut buf = BytesMut::new();
    let mut received = 0usize;
    while let Some(frame) = body.frame().await {
        let Ok(data) = frame?.into_data() else {
            continue; // trailers carry nothing we use
        };
        received = received.saturating_add(data.len());
        if received <= MAX_VALUE_LEN {
            buf.extend_from_slice(&data);
        } else if received > MAX_DRAIN_LEN {
            break;
        }
    }
    Ok((received <= MAX_VALUE_LEN).then(|| buf.freeze()))
}

//! Thread-safe in-memory key-value store.

use std::collections::BTreeMap;
use std::sync::{PoisonError, RwLock, RwLockReadGuard, RwLockWriteGuard};

use bytes::Bytes;

/// An in-memory map from keys to byte values, safe to share across tasks.
///
/// Keys are kept ordered so listing them is a simple in-order walk.
#[derive(Debug, Default)]
pub struct Store {
    entries: RwLock<BTreeMap<String, Bytes>>,
}

impl Store {
    pub fn new() -> Self {
        Self::default()
    }

    /// Stores `value` under `key`. Returns `true` if the key was new.
    pub fn put(&self, key: &str, value: Bytes) -> bool {
        let mut entries = self.write();
        match entries.get_mut(key) {
            Some(slot) => {
                *slot = value;
                false
            }
            None => {
                entries.insert(key.to_owned(), value);
                true
            }
        }
    }

    /// Returns the value stored under `key`, if any. Cloning `Bytes` is cheap.
    pub fn get(&self, key: &str) -> Option<Bytes> {
        self.read().get(key).cloned()
    }

    /// Removes `key`. Returns `true` if it was present.
    pub fn delete(&self, key: &str) -> bool {
        self.write().remove(key).is_some()
    }

    /// Returns every key in ascending byte order.
    pub fn keys(&self) -> Vec<String> {
        self.read().keys().cloned().collect()
    }

    // A panic while holding the lock cannot leave the map logically
    // inconsistent (every mutation is a single map call), so poisoning is
    // safe to ignore.
    fn read(&self) -> RwLockReadGuard<'_, BTreeMap<String, Bytes>> {
        self.entries.read().unwrap_or_else(PoisonError::into_inner)
    }

    fn write(&self) -> RwLockWriteGuard<'_, BTreeMap<String, Bytes>> {
        self.entries.write().unwrap_or_else(PoisonError::into_inner)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn put_get_delete() {
        let store = Store::new();
        assert!(store.put("a", Bytes::from_static(b"1")));
        assert!(!store.put("a", Bytes::from_static(b"2")));
        assert_eq!(store.get("a").as_deref(), Some(&b"2"[..]));
        assert!(store.delete("a"));
        assert!(!store.delete("a"));
        assert_eq!(store.get("a"), None);
    }

    #[test]
    fn keys_are_sorted() {
        let store = Store::new();
        for key in ["b", "a", "C", "_", "-", "0"] {
            store.put(key, Bytes::new());
        }
        assert_eq!(store.keys(), ["-", "0", "C", "_", "a", "b"]);
    }
}
